'use strict';

// MODULES //

var tape = require( 'tape' );
var hasProp = require( '@stdlib/assert/has-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var namedtypedtuple = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof namedtypedtuple, 'function', 'main export is a function' );
	t.end();
});

tape( 'a tuple has a `fill` method', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point();

	t.strictEqual( hasProp( p, 'fill' ), true, 'returns expected value' );
	t.strictEqual( isFunction( p.fill ), true, 'returns expected value' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a tuple instance', function test( t ) {
	var values;
	var Point;
	var p;
	var i;

	Point = namedtypedtuple( [ 'x', 'y' ] );
	p = new Point();

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[],
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return p.fill.call( value, 1 );
		};
	}
});

tape( 'the method returns the tuple', function test( t ) {
	var Point;
	var out;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );
	out = p.fill( 9 );

	t.strictEqual( out, p, 'returns expected value' );
	t.end();
});

tape( 'the method fills all tuple elements with a value', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	p.fill( 9 );

	t.strictEqual( p[ 0 ], 9, 'returns expected value' );
	t.strictEqual( p[ 1 ], 9, 'returns expected value' );
	t.strictEqual( p[ 2 ], 9, 'returns expected value' );

	// Field values reflect the update:
	t.strictEqual( p.x, 9, 'returns expected value' );
	t.strictEqual( p.y, 9, 'returns expected value' );
	t.strictEqual( p.z, 9, 'returns expected value' );
	t.end();
});

tape( 'the method fills tuple elements from a start index', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	p.fill( 9, 1 );

	t.strictEqual( p[ 0 ], 1, 'returns expected value' );
	t.strictEqual( p[ 1 ], 9, 'returns expected value' );
	t.strictEqual( p[ 2 ], 9, 'returns expected value' );

	// Field values reflect the update:
	t.strictEqual( p.x, 1, 'returns expected value' );
	t.strictEqual( p.y, 9, 'returns expected value' );
	t.strictEqual( p.z, 9, 'returns expected value' );
	t.end();
});

tape( 'the method fills tuple elements from a start index to an end index (non-inclusive)', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	p.fill( 9, 0, 2 );

	t.strictEqual( p[ 0 ], 9, 'returns expected value' );
	t.strictEqual( p[ 1 ], 9, 'returns expected value' );
	t.strictEqual( p[ 2 ], 3, 'returns expected value' );

	// Field values reflect the update:
	t.strictEqual( p.x, 9, 'returns expected value' );
	t.strictEqual( p.y, 9, 'returns expected value' );
	t.strictEqual( p.z, 3, 'returns expected value' );
	t.end();
});

tape( 'the method supports negative start indices', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	p.fill( 9, -2 );

	t.strictEqual( p[ 0 ], 1, 'returns expected value' );
	t.strictEqual( p[ 1 ], 9, 'returns expected value' );
	t.strictEqual( p[ 2 ], 9, 'returns expected value' );

	// Field values reflect the update:
	t.strictEqual( p.x, 1, 'returns expected value' );
	t.strictEqual( p.y, 9, 'returns expected value' );
	t.strictEqual( p.z, 9, 'returns expected value' );
	t.end();
});

tape( 'the method supports negative end indices', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	p.fill( 9, 0, -1 );

	t.strictEqual( p[ 0 ], 9, 'returns expected value' );
	t.strictEqual( p[ 1 ], 9, 'returns expected value' );
	t.strictEqual( p[ 2 ], 3, 'returns expected value' );

	// Field values reflect the update:
	t.strictEqual( p.x, 9, 'returns expected value' );
	t.strictEqual( p.y, 9, 'returns expected value' );
	t.strictEqual( p.z, 3, 'returns expected value' );
	t.end();
});

tape( 'the method is a no-op if the starting index is greater than or equal to the ending index', function test( t ) {
	var Point;
	var p;

	Point = namedtypedtuple( [ 'x', 'y', 'z' ] );
	p = new Point( [ 1, 2, 3 ] );

	p.fill( 9, 2, 1 );

	t.strictEqual( p[ 0 ], 1, 'returns expected value' );
	t.strictEqual( p[ 1 ], 2, 'returns expected value' );
	t.strictEqual( p[ 2 ], 3, 'returns expected value' );

	// Field values remain unchanged:
	t.strictEqual( p.x, 1, 'returns expected value' );
	t.strictEqual( p.y, 2, 'returns expected value' );
	t.strictEqual( p.z, 3, 'returns expected value' );
	t.end();
});
